export async function dynamicValues() {
  const literalText =
    (await import("./literal-text.txt", { with: { type: "text" } })).default;
  const literalJson =
    (await import("./literal-json.json", { with: { type: "json" } })).default;
  const literalBytes =
    (await import("./literal-bytes.bin", { with: { type: "bytes" } })).default;
  const computed = {
    text: "./computed-text.txt",
    json: "./computed-json.json",
    bytes: "./computed-bytes.bin",
  };
  const computedText =
    (await import(computed.text, { with: { type: "text" } })).default;
  const computedJson =
    (await import(computed.json, { with: { type: "json" } })).default;
  const computedBytes =
    (await import(computed.bytes, { with: { type: "bytes" } })).default;
  return {
    literalText: literalText.trim(),
    literalJson: literalJson.value,
    literalBytes: new TextDecoder().decode(literalBytes).trim(),
    computedText: computedText.trim(),
    computedJson: computedJson.value,
    computedBytes: new TextDecoder().decode(computedBytes).trim(),
  };
}
